ALTER TABLE institutional_inbox ALTER COLUMN body CLOB NOT NULL;
ALTER TABLE institutional_inbox ADD COLUMN document_kind VARCHAR(32) NOT NULL DEFAULT 'HISTORICO_V3';
CREATE TABLE institution_document(id VARCHAR(36) PRIMARY KEY,communication_id VARCHAR(36) NOT NULL,operation_id VARCHAR(36),attachment_id VARCHAR(36),origin VARCHAR(32) NOT NULL,name VARCHAR(180) NOT NULL,size_bytes BIGINT NOT NULL,sha256 CHAR(64) NOT NULL,media_type VARCHAR(100) NOT NULL,storage_key VARCHAR(80) NOT NULL,created_ms BIGINT NOT NULL,created_by VARCHAR(64),UNIQUE(operation_id,attachment_id),FOREIGN KEY(communication_id) REFERENCES communication_registry(comunicacion_id),FOREIGN KEY(created_by) REFERENCES core_actor(id),CHECK((origin='INGRESO_CIUDADANO' AND operation_id IS NOT NULL AND attachment_id IS NOT NULL AND created_by IS NULL) OR (origin='GESTION_INSTITUCIONAL' AND operation_id IS NULL AND attachment_id IS NULL AND created_by IS NOT NULL)));
CREATE INDEX ix_document_communication ON institution_document(communication_id,id);
CREATE VIEW institution_document_case AS SELECT d.id AS document_id,c.id AS case_id FROM institution_document d JOIN core_case c ON c.communication_id=d.communication_id WHERE d.origin='INGRESO_CIUDADANO';
CREATE VIEW institution_document_requirement AS SELECT d.id AS document_id,r.id AS requirement_id FROM institution_document d JOIN core_requirement r ON r.communication_id=d.communication_id WHERE d.origin='INGRESO_CIUDADANO';
CREATE TABLE institution_document_access(seq BIGINT AUTO_INCREMENT PRIMARY KEY,document_id VARCHAR(36) NOT NULL,communication_id VARCHAR(36) NOT NULL,actor_id VARCHAR(64) NOT NULL,at_ms BIGINT NOT NULL,representation VARCHAR(24) NOT NULL,FOREIGN KEY(document_id) REFERENCES institution_document(id),FOREIGN KEY(communication_id) REFERENCES communication_registry(comunicacion_id),FOREIGN KEY(actor_id) REFERENCES core_actor(id));
